DATA=''

def load(source,unit):
    f=pd.read_csv(source)
    if f.shape[1]!=2: raise ValueError('CSV must have date and price columns.')
    dates=pd.to_datetime(f.iloc[:,0],errors='raise').dt.normalize()
    p=pd.Series(pd.to_numeric(f.iloc[:,1],errors='raise').to_numpy(),index=pd.DatetimeIndex(dates)).sort_index()
    if len(p)<2 or p.index.hasnans or p.index.has_duplicates or not np.isfinite(p).all() or (p<=0).any():
        raise ValueError('Supply unique valid dates and positive finite prices.')
    return p*42 if unit=='USD/gal' else p

def apo(f,k,times,sigma):
    t=np.asarray(times,dtype=float)
    variance=np.log1p(np.expm1(sigma*sigma*np.minimum.outer(t,t)).mean())
    if variance<1e-14: return max(f-k,0.)
    z=np.sqrt(variance); d=(np.log(f/k)+variance/2)/z
    return max(0.,f*norm.cdf(d)-k*norm.cdf(d-z))

def trade_engine(px,cal,start,budget,annual,ratio,otm,lo,hi,mode,flat,floor,vrp,tc):
    months=pd.period_range(px.index.min(),px.index.max(),freq='M')
    future=pd.period_range(months[0],months[-1]+hi,freq='M')
    schedules={m:pd.date_range(m.start_time,m.end_time.normalize(),freq=cal) for m in future}
    rv=np.log(px).diff().rolling(252,min_periods=60).std().shift(1)*np.sqrt(252)
    qtarget=annual/12*ratio/(hi-lo+1); spent={}; rows=[]
    for m in months:
        dates=schedules[m]
        if not len(dates): continue
        buy=dates[0]
        if buy<start or buy not in px.index: continue
        spot=float(px.loc[buy]); r=rv.get(buy,np.nan)
        base=flat if mode=='Flat' else max(floor,r if pd.notna(r) else flat)
        sigma=max(.01,base+vrp); candidates=[]
        for h in range(lo,hi+1):
            delivery=m+h; fix=schedules[delivery]
            if not len(fix): continue
            k=spot*(1+otm)
            premium=apo(spot,k,(fix-buy).days.to_numpy()/365.,sigma)*(1+tc)
            candidates.append((h,delivery,fix,k,premium))
        required=sum(x[4]*qtarget for x in candidates)
        available=max(0.,budget-spent.get(buy.year,0.))
        scale=min(1.,available/required) if required>0 else 1.
        for h,delivery,fix,k,p in candidates:
            q=qtarget*scale
            settled=bool(fix[-1]<=px.index.max() and fix.isin(px.index).all())
            avg=float(px.loc[fix].mean()) if settled else np.nan
            swap=(avg-spot)*qtarget if settled else np.nan
            call=max(avg-k,0.)*q if settled else np.nan
            rows.append(dict(buy=buy,buy_month=buy.to_period('M').to_timestamp(),delivery_month=delivery.to_timestamp(),
                settlement_date=fix[-1],tenor=h,fixings=len(fix),spot=spot,vol=sigma,call_strike=k,swap_strike=spot,
                monthly_average=avg,target_bbl=qtarget,call_bbl=q,swap_bbl=qtarget,
                required_premium=p*qtarget,premium_bbl=p,premium_paid=p*q,
                status='Settled' if settled else 'Live',call_received=call,
                swap_received=max(swap,0.) if settled else np.nan,
                swap_paid=max(-swap,0.) if settled else np.nan))
            spent[buy.year]=spent.get(buy.year,0.)+p*q
    return pd.DataFrame(rows),schedules

def swap_valuation(px,trades,schedules,start):
    idx=px.index[px.index>=start]
    result=pd.DataFrame(0.,index=idx,columns=['positive_mtm','negative_mtm','net_mtm','settlement_cash','live_bbl','live_count'])
    for row in trades.itertuples():
        fixing=schedules[row.delivery_month.to_period('M')]
        obs=px.reindex(fixing)
        live=idx[(idx>=row.buy)&(idx<row.settlement_date)]
        if len(live):
            observed_dates=fixing[fixing<=px.index.max()]
            observed_values=obs.loc[observed_dates].to_numpy()
            if np.isnan(observed_values).any():
                raise ValueError('Missing past fixing: MTM cannot be calculated reliably.')
            prefix=np.r_[0.,np.cumsum(observed_values)]
            n=observed_dates.searchsorted(live,side='right')
            estimated=(prefix[n]+(len(fixing)-n)*px.loc[live].to_numpy())/len(fixing)
            value=row.swap_bbl*(estimated-row.swap_strike)
            result.loc[live,'positive_mtm']+=np.maximum(value,0.)
            result.loc[live,'negative_mtm']+=np.minimum(value,0.)
            result.loc[live,'live_bbl']+=row.swap_bbl
            result.loc[live,'live_count']+=1
        if row.status=='Settled' and row.settlement_date in result.index:
            result.loc[row.settlement_date,'settlement_cash']+=row.swap_received-row.swap_paid
    result['net_mtm']=result.positive_mtm+result.negative_mtm
    result['cumulative_realised_cash']=result.settlement_cash.cumsum()
    result['total_swap_pnl']=result.cumulative_realised_cash+result.net_mtm
    return result

