    missing=expected.difference(px.index)
    if len(missing): raise ValueError('Missing expected publication dates. Configure holidays or repair data. First gaps: '+', '.join(missing[:10].strftime('%Y-%m-%d')))
    if len(px)<2: raise ValueError('Too few prices after applying calendar.')
